     * Функция проверяет, является ли окружение производственным, прежде чем подавить детали трассировки.
     */
    public static String getDebugInfo(Throwable e, boolean isProduction) {
        if (e == null) {
            return "";
        }

        if (isProduction) {
            // В производственной среде возвращаем только сообщение об ошибке, без трассировки стека
            return "An error occurred: " + e.getMessage();
        } else {
            // В непроизводственной среде возвращаем полную трассировку стека
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            return sw.toString();
        }
    }

    // Пример использования (опционально, для демонстрации)
    public static void main(String[] args) {
        try {
            int result = 10 / 0; // Вызовем исключение
        } catch (Exception e) {
            System.out.println("--- Debug Info (Development) ---");
            System.out.println(getDebugInfo(e, false)); // false для непроизводственной среды

            System.out.println("\n--- Debug Info (Production) ---");
            System.out.println(getDebugInfo(e, true));  // true для производственной среды
        }

        System.out.println("\n--- Debug Info (Null Throwable) ---");
        System.out.println(getDebugInfo(null, false));
    }
}
