     *
     * @return true si l'environnement est en production, false sinon.
     */
    private boolean isProductionEnvironment() {
        String env = System.getenv(PRODUCTION_ENV_VAR);
        return PRODUCTION_ENV_VALUE.equalsIgnoreCase(env);
    }
