import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class ClassX {
    /**
     * Parses XML-dokumendi.
     * 
     * Funktsioon kontrollib 'DOCTYPE' deklaratsioonide olemasolu, et vältida XXE-d.
     * 
     * @param xmlString XML-string, mida parsida.
     * @return Parsitud XML-dokument.
     * @throws Exception Kui XML-i parsimisel tekib viga või kui DOCTYPE deklaratsioon on leitud.
     */
    public Document parseXml(String xmlString) throws Exception {
        if (xmlString.contains("<!DOCTYPE")) {
            throw new Exception("DOCTYPE deklaratsioonid ei ole lubatud XXE rünnakute vältimiseks.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Keela välised üldised üksused
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Keela välised parameetri üksused
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Keela DTD-de laadimine
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Keela XInclude
        factory.setXIncludeAware(false);
        // Keela skeemide valideerimine, mis võib samuti väliseid ressursse laadida
        factory.setValidating(false);

        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.parse(new ByteArrayInputStream(xmlString.getBytes()));
    }
}
